// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.agenticimport com.roshan.persona.common.CorrelationIdimport java.time.Instant/** * NOUS — Workflow trace (audit log of an agentic workflow). * * Records every step of a ReAct workflow for: *   - **Audit log** — every tool call, every LLM query, every cost *   - **Debugging** — replay the workflow to see what went wrong *   - **Cost tracking** — sum of all step costs *   - **Performance analysis** — per-step latency *   - **User transparency** — show in Settings → AI → Workflow History * * ## Lifecycle * *   1. [WorkflowTraceBuilder] created at workflow start *   2. Each step recorded via [WorkflowTraceBuilder.recordStep] *   3. On completion, [WorkflowTraceBuilder.build] produces immutable [WorkflowTrace] *   4. Trace persisted to Room (`workflow_traces` table) in Module 3 *   5. Trace also emitted via [com.roshan.persona.brain.bus.BrainEvent] for live UI * * ## Privacy * *   - Trace is stored ON-DEVICE only (never synced to cloud) *   - Tool params may contain PII — stored in trace but never transmitted *   - User can view + delete traces in Settings → AI → Workflow History *   - Traces auto-expire after 30 days (configurable) * * @see <a href="docs/spec/module2-spec-review.pdf">§9.5 WorkflowTrace</a> */data class WorkflowTrace(    /** Unique workflow ID (UUID). */    val workflowId: String,    /** Correlation ID of the originating user request. */    val correlationId: CorrelationId,    /** Session ID (links to conversation). */    val sessionId: com.roshan.persona.brain.context.SessionId,    /** When the workflow started. */    val startedAt: Instant,    /** When the workflow ended. */    val endedAt: Instant,    /** All steps in execution order. */    val steps: List<WorkflowStep>,    /** Total wall-clock duration in milliseconds. */    val totalDurationMs: Long,    /** Total USD cost (sum of all step costs). */    val totalCostUsd: Float,    /** Final status (completed / failed / max_steps / budget / timeout). */    val finalStatus: WorkflowStatus,    /** Final answer text (null if workflow failed before producing one). */    val finalAnswer: String?,    /** User input that triggered this workflow. */    val userInput: String,    /** Optional failure reason (if finalStatus != COMPLETED). */    val failureReason: String? = null,) {    /** Number of steps executed. */    val stepCount: Int get() = steps.size    /** Total tokens used across all LLM queries. */    val totalTokensUsed: Int        get() = steps.sumOf { step ->            when (val result = step.observation) {                is AgenticStepResult.LlmSuccess -> result.tokensUsed                else -> 0            }        }    /** Number of tool calls made. */    val toolCallCount: Int        get() = steps.count { it.action is AgenticStep.ToolCall }    /** Number of LLM queries made. */    val llmQueryCount: Int        get() = steps.count { it.action is AgenticStep.LlmQuery }    /** Whether the workflow succeeded. */    val isCompleted: Boolean get() = finalStatus == WorkflowStatus.COMPLETED}/** * One step in a workflow trace. */data class WorkflowStep(    /** Step number (1-indexed). */    val stepNumber: Int,    /** LLM's reasoning before this action (null for the first step). */    val thought: String?,    /** The action taken. */    val action: AgenticStep,    /** Result of the action (null if action is FinalAnswer). */    val observation: AgenticStepResult?,    /** Wall-clock duration of this step, in milliseconds. */    val durationMs: Long,    /** USD cost of this step (0 for free tools). */    val costUsd: Float,    /** When this step started. */    val startedAt: Instant,)/** * Final status of a workflow. */enum class WorkflowStatus {    /** Workflow produced a final answer successfully. */    COMPLETED,    /** Workflow failed (tool error, LLM error, critic gave up). */    FAILED,    /** Workflow hit the max steps limit (default 10). */    MAX_STEPS_EXCEEDED,    /** Workflow hit the budget cap (default from [com.roshan.persona.brain.context.BrainBudget]). */    BUDGET_EXCEEDED,    /** Workflow hit the time cap. */    TIMEOUT,    /** Workflow was cancelled by the user. */    CANCELLED,}/** * Mutable builder for [WorkflowTrace]. Used by [AgenticOrchestrator] during * workflow execution, then `build()` produces the immutable trace. */class WorkflowTraceBuilder(    val workflowId: String,    val correlationId: CorrelationId,    val sessionId: com.roshan.persona.brain.context.SessionId,    val userInput: String,    private val startedAt: Instant = Instant.now(),) {    private val steps = java.util.concurrent.CopyOnWriteArrayList<WorkflowStep>()    private var totalCostUsd = 0f    /** Record a completed step. */    fun recordStep(        thought: String?,        action: AgenticStep,        observation: AgenticStepResult?,        durationMs: Long,        costUsd: Float,        startedAt: Instant = Instant.now(),    ) {        val step = WorkflowStep(            stepNumber = steps.size + 1,            thought = thought,            action = action,            observation = observation,            durationMs = durationMs,            costUsd = costUsd,            startedAt = startedAt,        )        steps.add(step)        totalCostUsd += costUsd    }    /** Current step count. */    fun stepCount(): Int = steps.size    /** Current total cost. */    fun currentCost(): Float = totalCostUsd    /** Get all steps so far (immutable copy). */    fun getSteps(): List<WorkflowStep> = steps.toList()    /**     * Build the final immutable trace.     */    fun build(        finalStatus: WorkflowStatus,        finalAnswer: String?,        failureReason: String? = null,    ): WorkflowTrace {        val now = Instant.now()        return WorkflowTrace(            workflowId = workflowId,            correlationId = correlationId,            sessionId = sessionId,            startedAt = startedAt,            endedAt = now,            steps = steps.toList(),            totalDurationMs = now.toEpochMilli() - startedAt.toEpochMilli(),            totalCostUsd = totalCostUsd,            finalStatus = finalStatus,            finalAnswer = finalAnswer,            userInput = userInput,            failureReason = failureReason,        )    }}